(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w2 = Math.cos(x*0.011-y*0.009+t*0.18)*8 + Math.sin(y*0.016+x*0.007-t*0.25)*6;
  const sx = x + w1 + w2, sy = y + w1*0.6 - w2;
  const warp2 = Math.sin(sx*0.02+sy*0.015+t*0.5)*10 + Math.cos(sx*0.015-sy*0.02-t*0.4)*8;
  const fx = sx + warp2, fy = sy + warp2*0.7;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.95],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.05],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+1)*65, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+4)*55, 0.065, 2.4, 1.15]
  ];
  let aS=0, iS=0, harm=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2 + (fy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    harm += Math.sin(d*f*0.5 - t*sp*0.3 + 0.8) * w;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, hrm = harm/n;
  const bg1 = Math.sin(fx*0.04+fy*0.025+t*0.8);
  const bg2 = Math.sin(fx*0.03-fy*0.04+t*1.1);
  const bg3 = Math.sin((fx+fy)*0.12+t*2.5)*0.2;
  const bg4 = Math.sin((fx-fy)*0.1-t*2)*0.2;
  const bg = (bg1+bg2)/2 + bg3 + bg4;
  const dist = Math.sqrt((fx-cx)**2 + (fy-cy)**2);
  const ang = Math.atan2(fy-cy, fx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.07-ang*2+t*0.8)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const micro = Math.sin(fx*0.31+t*3.2)*Math.sin(fy*0.29-t*2.8)*0.15;
  const feed = act - inh*0.65 + bg*0.25 + spiral*0.6 + hrm*0.2 + micro;
  const reaction = Math.tanh(feed*2.0);
  const cell = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15) + Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.25;
  const ridge = Math.exp(-Math.abs(reaction)*3.0)*0.4;
  const blend = reaction*0.65 + cell*0.15 + ridge*0.2;
  const v = blend*0.5+0.5;
  const pal = [
    [6,14,52],[10,42,82],[14,78,108],[18,118,118],
    [45,148,112],[110,168,95],[175,178,72],[210,175,60],
    [220,155,75],[215,125,80],[190,90,78],[150,60,70],
    [100,38,62],[55,22,55],[20,14,50],[6,14,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const r = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.82 + Math.sin(reaction*Math.PI)*0.18;
  const glow = Math.max(0, reaction)*0.3;
  const edge = Math.abs(reaction)>0.65 ? 1.12 : 1.0;
  const sh = (1.0 - Math.abs(reaction)*0.15);
  return [
    Math.min(255, (r*lum*edge + glow*40)*sh)|0,
    Math.min(255, (g*lum*edge + glow*30)*sh)|0,
    Math.min(255, (b*lum*edge + glow*15)*sh)|0
  ];
}
